    "drawingSvg": "<svg viewBox=\"0 0 240 145\" class=\"w-full h-full\"><defs><marker id=\"arr-21301\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"5\" markerHeight=\"5\" orient=\"auto-start-reverse\"><path d=\"M 0 1.5 L 8 5 L 0 8.5 z\" fill=\"#000000\"/></marker></defs><line x1=\"120\" y1=\"72\" x2=\"190\" y2=\"72\" stroke=\"#000000\" stroke-width=\"2.4\" marker-end=\"url(#arr-21301)\"/><line x1=\"120\" y1=\"72\" x2=\"120\" y2=\"20\" stroke=\"#000000\" stroke-width=\"2.4\" marker-end=\"url(#arr-21301)\"/><line x1=\"120\" y1=\"72\" x2=\"70\" y2=\"112\" stroke=\"#000000\" stroke-width=\"2.4\" marker-end=\"url(#arr-21301)\"/><rect x=\"120\" y=\"62\" width=\"10\" height=\"10\" rx=\"0\" fill=\"none\" stroke=\"#000000\" stroke-width=\"1.1\"/><text x=\"194\" y=\"76\" font-size=\"10\" font-family=\"sans-serif\" font-style=\"normal\" font-weight=\"bold\" text-anchor=\"start\" fill=\"#000000\">e\u2081</text><text x=\"124\" y=\"16\" font-size=\"10\" font-family=\"sans-serif\" font-style=\"normal\" font-weight=\"bold\" text-anchor=\"start\" fill=\"#000000\">e\u2082</text><text x=\"66\" y=\"122\" font-size=\"10\" font-family=\"sans-serif\" font-style=\"normal\" font-weight=\"bold\" text-anchor=\"end\" fill=\"#000000\">e\u2083</text><text x=\"20\" y=\"24\" font-size=\"10\" font-family=\"sans-serif\" font-style=\"normal\" font-weight=\"bold\" text-anchor=\"start\" fill=\"#000000\">T normal \u21d4</text><text x=\"20\" y=\"40\" font-size=\"9\" font-family=\"sans-serif\" font-style=\"normal\" font-weight=\"normal\" text-anchor=\"start\" fill=\"#000000\">\u2203 orthonormal basis</text><text x=\"20\" y=\"54\" font-size=\"9\" font-family=\"sans-serif\" font-style=\"normal\" font-weight=\"normal\" text-anchor=\"start\" fill=\"#000000\">of eigenvectors</text><text x=\"20\" y=\"128\" font-size=\"9.5\" font-family=\"sans-serif\" font-style=\"normal\" font-weight=\"bold\" text-anchor=\"start\" fill=\"#000000\">T = U D U*,  U unitary</text><text x=\"160\" y=\"128\" font-size=\"9\" font-family=\"sans-serif\" font-style=\"normal\" font-weight=\"normal\" text-anchor=\"start\" fill=\"#000000\">D = diag(\u03bb\u2c7c)</text></svg>",
    "drawingCaption": "Normal operators can be diagonalized with perpendicular axes: just rotate your coordinate system",
